-- Sport Performance clean install. Run only in a NEW/empty Supabase project after review.
-- No audit-log table, triggers, RPC, or fabricated BARÈME data.
create extension if not exists pgcrypto;
create type public.member_role as enum ('platform_owner','institution_admin','admin','coach');
create type public.member_status as enum ('pending','active','rejected','suspended');
create type public.attendance_status as enum ('present','absent','late');
create table public.institutions(id uuid primary key default gen_random_uuid(),name text not null,slug text unique,logo_url text,watermark_url text,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',email text not null default '',role public.member_role not null default 'coach',status public.member_status not null default 'pending',institution_id uuid references public.institutions(id),created_at timestamptz not null default now());
create table public.school_years(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),name text not null,start_date date not null,end_date date,is_current boolean not null default false,archived_at timestamptz,created_at timestamptz not null default now(),unique(institution_id,name));
create unique index one_current_year_per_institution on public.school_years(institution_id) where is_current;
create table public.classes(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),school_year_id uuid not null references public.school_years(id),name text not null,created_at timestamptz default now(),unique(institution_id,school_year_id,name));
create table public.students(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),school_year_id uuid not null references public.school_years(id),class_id uuid references public.classes(id),student_number text not null,full_name text not null,gender text,birth_date date,archived boolean not null default false,created_at timestamptz default now(),unique(institution_id,school_year_id,student_number));
create table public.lesson_plans(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),school_year_id uuid not null references public.school_years(id),title text not null,content text default '',file_path text,created_by uuid references auth.users(id),created_at timestamptz default now());
create table public.sessions(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),school_year_id uuid not null references public.school_years(id),coach_id uuid not null references auth.users(id),coach_name_snapshot text not null,lesson_plan_id uuid references public.lesson_plans(id),session_date date not null default current_date,start_time time not null,end_time time,duration_minutes integer generated always as (case when end_time is null then null else greatest(0,round(extract(epoch from (end_time-start_time))/60)::integer) end) stored,notes text default '',created_at timestamptz default now(),check(end_time is null or end_time>=start_time));
create table public.attendance(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),school_year_id uuid not null references public.school_years(id),student_id uuid not null references public.students(id),session_id uuid references public.sessions(id),attendance_date date not null,status public.attendance_status not null,absence_reason text check(absence_reason is null or absence_reason in ('ordinary','permission','exempt','official_duty')),is_late boolean not null default false,recorded_by uuid references auth.users(id),created_at timestamptz default now(),unique nulls not distinct(student_id,attendance_date,session_id));
create table public.test_definitions(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),name text not null,unit text not null default '',higher_is_better boolean not null default true,is_active boolean not null default true,created_at timestamptz default now(),unique(institution_id,name));
create table public.scale_versions(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),test_id uuid not null references public.test_definitions(id),version integer not null,valid_from date not null,rules jsonb not null check(jsonb_typeof(rules)='array'),created_by uuid references auth.users(id),created_at timestamptz default now(),unique(test_id,version));
create table public.test_results(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),school_year_id uuid not null references public.school_years(id),student_id uuid not null references public.students(id),test_id uuid not null references public.test_definitions(id),scale_version_id uuid references public.scale_versions(id),raw_value numeric(10,3) not null,score numeric(8,3),tested_on date not null default current_date,recorded_by uuid references auth.users(id),created_at timestamptz default now());
create table public.student_measurements(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),school_year_id uuid not null references public.school_years(id),student_id uuid not null references public.students(id),weight_kg numeric(6,2),height_m numeric(4,3),bmi numeric(6,2),measured_on date not null default current_date,created_by uuid references auth.users(id),created_at timestamptz default now(),check(weight_kg is null or weight_kg>0),check(height_m is null or height_m>0));
create table public.observations(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),school_year_id uuid not null references public.school_years(id),student_id uuid not null references public.students(id),author_id uuid not null references auth.users(id),body text not null,created_at timestamptz default now());
create table public.coach_notebook(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),owner_id uuid not null references auth.users(id),body text not null,created_at timestamptz default now());
create table public.rehab_alerts(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),school_year_id uuid not null references public.school_years(id),student_id uuid not null references public.students(id),triggered_on date not null,remaining_sessions integer not null default 2 check(remaining_sessions between 0 and 2),handled_at timestamptz,created_at timestamptz default now());
create table public.institution_memberships(id uuid primary key default gen_random_uuid(),institution_id uuid not null references public.institutions(id),user_id uuid not null references auth.users(id),role public.member_role not null,status public.member_status not null default 'pending',created_at timestamptz default now(),unique(institution_id,user_id));
create index students_year_class_idx on public.students(school_year_id,class_id);
create index attendance_year_date_idx on public.attendance(school_year_id,attendance_date);
create index results_student_date_idx on public.test_results(student_id,tested_on desc);
create index sessions_coach_date_idx on public.sessions(coach_id,session_date desc);
create index measurements_student_date_idx on public.student_measurements(student_id,measured_on desc);
create or replace function public.current_institution_id() returns uuid language sql stable security definer set search_path=public as $$ select institution_id from public.profiles where id=auth.uid() and status='active' $$;
create or replace function public.current_member_role() returns public.member_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() and status='active' $$;
create or replace function public.is_institution_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_member_role() in ('platform_owner','institution_admin','admin'),false) $$;
create or replace function public.guard_active_year() returns trigger language plpgsql as $$ declare y uuid; begin y:=coalesce(new.school_year_id,old.school_year_id); if exists(select 1 from public.school_years where id=y and archived_at is not null) then raise exception 'Archived school year is read-only'; end if; if tg_op='DELETE' then return old; else return new; end if; end $$;
-- Enforce archived-year immutability on all year-owned operational tables.
do $$ declare t text; begin foreach t in array array['classes','students','lesson_plans','sessions','attendance','test_results','student_measurements','observations','rehab_alerts'] loop execute format('create trigger %I before insert or update or delete on public.%I for each row execute function public.guard_active_year()',t||'_active_year_guard',t); end loop; end $$;
create or replace function public.create_school_year(p_name text,p_start_date date) returns uuid language plpgsql security definer set search_path=public as $$ declare i uuid; n uuid; begin i:=public.current_institution_id(); if i is null or not public.is_institution_admin() then raise exception 'Not authorized'; end if; update public.school_years set is_current=false,end_date=p_start_date-1,archived_at=now() where institution_id=i and is_current=true; insert into public.school_years(institution_id,name,start_date,is_current) values(i,p_name,p_start_date,true) returning id into n; return n; end $$;
-- RLS helpers: institution boundary + role-aware writes.
do $$ declare t text; begin foreach t in array array['institutions','profiles','school_years','classes','students','lesson_plans','sessions','attendance','test_definitions','scale_versions','test_results','student_measurements','observations','coach_notebook','rehab_alerts','institution_memberships'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy institution_read on public.institutions for select to authenticated using(id=public.current_institution_id());
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or institution_id=public.current_institution_id() and public.is_institution_admin());
-- No self-service profile UPDATE: users must never promote their own role/status.
-- Profile role/status changes are reserved for trusted provisioning (SQL/service-side workflow).
create policy members_read on public.institution_memberships for select to authenticated using(institution_id=public.current_institution_id());
create policy years_read on public.school_years for select to authenticated using(institution_id=public.current_institution_id());
create policy years_admin_write on public.school_years for all to authenticated using(institution_id=public.current_institution_id() and public.is_institution_admin()) with check(institution_id=public.current_institution_id() and public.is_institution_admin());
do $$ declare t text; begin foreach t in array array['classes','students','lesson_plans','sessions','attendance','test_definitions','scale_versions','test_results','student_measurements','observations','rehab_alerts'] loop execute format('create policy %I on public.%I for select to authenticated using(institution_id=public.current_institution_id())',t||'_read',t); execute format('create policy %I on public.%I for insert to authenticated with check(institution_id=public.current_institution_id() and public.is_institution_admin())',t||'_admin_insert',t); execute format('create policy %I on public.%I for update to authenticated using(institution_id=public.current_institution_id() and public.is_institution_admin()) with check(institution_id=public.current_institution_id() and public.is_institution_admin())',t||'_admin_update',t); execute format('create policy %I on public.%I for delete to authenticated using(institution_id=public.current_institution_id() and public.is_institution_admin())',t||'_admin_delete',t); end loop; end $$;
-- Coaches may create/update their own sessions and attendance they record; archived years remain guarded.
create policy coach_session_insert on public.sessions for insert to authenticated with check(institution_id=public.current_institution_id() and coach_id=auth.uid());
create policy coach_session_update on public.sessions for update to authenticated using(coach_id=auth.uid() and institution_id=public.current_institution_id()) with check(coach_id=auth.uid() and institution_id=public.current_institution_id());
create policy coach_attendance_insert on public.attendance for insert to authenticated with check(institution_id=public.current_institution_id() and recorded_by=auth.uid());
create policy coach_attendance_update on public.attendance for update to authenticated using(recorded_by=auth.uid() and institution_id=public.current_institution_id()) with check(recorded_by=auth.uid() and institution_id=public.current_institution_id());
create policy notebook_owner_all on public.coach_notebook for all to authenticated using(owner_id=auth.uid() and institution_id=public.current_institution_id()) with check(owner_id=auth.uid() and institution_id=public.current_institution_id());
grant usage on schema public to authenticated;
grant select,insert,update,delete on all tables in schema public to authenticated;
grant execute on function public.create_school_year(text,date) to authenticated;
-- Attendance uniqueness includes session; NULL session values are treated as equal (PostgreSQL 15+).
